-- 统一多参数输入分隔符：分号 -> 空格（逗号保留，因为部分题目里逗号是数据本身）。
-- 历史数据（判题用例与示例的输入）与题面措辞一起改，保证"示例 = 判题真实输入"这一不变量继续成立。
UPDATE test_cases SET input_text = REPLACE(input_text, ';', ' ') WHERE input_text LIKE '%;%';
UPDATE examples SET input_text = REPLACE(input_text, ';', ' ') WHERE input_text LIKE '%;%';
